SELECT id, units, revenue, SUM(units) OVER (PARTITION BY product_id ORDER BY units, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_units, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY revenue DESC, id) AS seq_no, LAST_VALUE(units) IGNORE NULLS OVER (PARTITION BY product_id ORDER BY sale_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_units FROM store_sales WHERE store_id IN (1, 3, 4);
